const botao = document.querySelector('#botao');
const contador = document.querySelector('#contador');
let total = 0;

botao.addEventListener('click', () => {
  total += 1;
  contador.textContent = total;
});

const nome = document.querySelector('#nome');
const saida = document.querySelector('#saida');

nome.addEventListener('input', () => {
  saida.textContent = nome.value;
});

const itens = document.querySelectorAll('#lista li');

for (let i = 0; i < itens.length; i += 1) {
  itens[i].classList.add('destaque');
}

const nome = document.querySelector('#nome');
const botao = document.querySelector('#saudar');
const saudacao = document.querySelector('#saudacao');

botao.addEventListener('click', () => {
  saudacao.textContent = `Olá, ${nome.value}!`;
});

const valores = [10, 20, 30];
const botao = document.querySelector('#somar');
const total = document.querySelector('#total');

function somar(lista) {
  let soma = 0;
  for (let i = 0; i < lista.length; i += 1) {
    soma += lista[i];
  }
  return soma;
}

botao.addEventListener('click', () => {
  total.textContent = somar(valores);
});
